/* ───────── Категория ───────── */
CATS.text_recall = {
  name: 'Внимание к тексту', desc: 'Прочитай фрагмент и ответь на вопрос по памяти',
  icon: '👁️', bg: '#e1f5ee', fg: '#085041',
  gen() {
    const lvl = getLvl();
    // только фрагменты выбранного уровня (если их нет — ближайший меньший)
    let pool = TR_ITEMS.filter(x => x.lvl === lvl.id);
    for (let l = lvl.id - 1; !pool.length && l >= 1; l--) pool = TR_ITEMS.filter(x => x.lvl === l);
    if (!pool.length) pool = TR_ITEMS;
    // не повторять недавние, пока не покажем весь пул
    let fresh = pool.filter(x => !TR_SEEN.includes(x));
    if (!fresh.length) { TR_SEEN.length = 0; fresh = pool; }
    const item = pick(fresh);
    TR_SEEN.push(item);
    return { type: 'text_recall', item };
  }
};
const TR_SEEN = [];

/* ───────── Вспомогательные ───────── */
// дефис — разделитель слов: «темно-зеленым» → «темно», «зеленым»; «3-й» → «3», «й»
const trWords = s => s.toLowerCase().replace(/ё/g, 'е').replace(/[^а-яa-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
const trEsc = s => s.replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

// возвращает { ok, hit, total }
function trCheck(item, input) {
  const padded = ' ' + trWords(input).join(' ') + ' ';
  const hits = item.keys.map(group => group.some(raw => {
    const s = raw.toLowerCase().replace(/ё/g, 'е');
    return /^\d+$/.test(s) ? padded.includes(' ' + s + ' ') : padded.includes(' ' + s);
  }));
  const hit = hits.filter(Boolean).length;
  return { ok: hit === item.keys.length, hit, total: item.keys.length };
}


// слово из текста подходит под группу ключей? (цифры — целиком, остальное — по началу слова)
function trTokenMatches(token, item) {
  const t = token.toLowerCase().replace(/ё/g, 'е');
  return item.keys.some(group => group.some(raw => {
    const k = raw.toLowerCase().replace(/ё/g, 'е');
    return /^\d+$/.test(k) ? t === k : t.startsWith(k);
  }));
}
const TR_TOKEN = /[А-Яа-яЁёA-Za-z0-9]+/g;

// «Правильный ответ»: только нужные слова, как они стоят в тексте
function trKeyWords(item) {
  const out = [];
  const scan = str => (str.match(TR_TOKEN) || []).forEach(w => {
    if (trTokenMatches(w, item) && !out.includes(w)) out.push(w);
  });
  (item.hl || []).forEach(scan);
  if (!out.length) scan(item.text);
  return out.length ? out.join(', ') : item.a;
}

// фрагмент ответа: ключевые слова подчёркнуты
function trMarkFragment(frag, item) {
  let html = '', last = 0, m;
  TR_TOKEN.lastIndex = 0;
  while ((m = TR_TOKEN.exec(frag))) {
    html += trEsc(frag.slice(last, m.index));
    const w = trEsc(m[0]);
    html += trTokenMatches(m[0], item) ? `<u class="tr-key">${w}</u>` : w;
    last = m.index + m[0].length;
  }
  return html + trEsc(frag.slice(last));
}

// весь текст: нужное место — цветом, ключевые слова внутри — подчёркнуты
function trHighlight(item) {
  let html = trEsc(item.text);
  (item.hl || []).forEach(h => {
    const e = trEsc(h);
    if (html.includes(e)) html = html.replace(e, `<mark class="tr-hl">${trMarkFragment(h, item)}</mark>`);
  });
  return html;
}

// подпись источника: название + ссылка «Источник >>» (если есть)
function trSource(item) {
  const link = item.url
    ? ` · <a class="tr-link" href="${item.url}" target="_blank" rel="noopener">Источник &gt;&gt;</a>` : '';
  return `<div class="tr-src">— ${trEsc(item.src)}${link}</div>`;
}

/* ───────── Отрисовка ───────── */
function renderTextRecall() {
  const it = STATE.curTask.item;
  if (typeof stopTimer === 'function') stopTimer();
  STATE.scratch = { phase: 'read' };

  document.getElementById('task-area').innerHTML = `
    <div class="task-q"><span class="tr-title">Прочитай фрагмент внимательно</span>
      <span class="tr-hint">Потом текст скроется, и нужно будет ответить на вопрос</span></div>
    <div class="task-vis tr-text">${trEsc(it.text)}
      <div class="tr-src">— ${trEsc(it.src)}</div></div>
    <div class="tr-row">
      <button class="btn-sm btn-main" onclick="trReady()">Я готов — показать вопрос</button>
    </div>`;
}

function trReady() {
  const it = STATE.curTask.item;
  STATE.scratch.phase = 'ask';
  document.getElementById('task-area').innerHTML = `
    <div class="task-q">${trEsc(it.q)}</div>
    <input id="tr-in" class="tr-input" type="text" autocomplete="off" autocapitalize="off"
           placeholder="Твой ответ…" onkeydown="if(event.key==='Enter')trSubmit()">
    <div class="tr-row">
      <button class="btn-sm btn-main" onclick="trSubmit()">Проверить</button>
      <button class="btn-sm" onclick="trGiveUp()">Не помню</button>
    </div>`;
  const inp = document.getElementById('tr-in');
  if (inp) inp.focus();
}

function trSubmit() {
  const inp = document.getElementById('tr-in');
  if (!inp || !inp.value.trim()) return;
  trFinish(inp.value.trim());
}
function trGiveUp() { trFinish(''); }

function trFinish(userAns) {
  if (STATE.answered) return;
  const it = STATE.curTask.item;
  const r = userAns ? trCheck(it, userAns) : { ok: false, hit: 0, total: it.keys.length };
  STATE.scratch.phase = 'done';
  STATE.answered = true;

  // верно — звезда; частично — тоже засчитываем (одна звезда)
  const credited = r.ok || r.hit > 0;
  STATE.scTot++; if (credited) STATE.scOk++;

  let cls, mark;
  if (r.ok)           { cls = 'ok';   mark = '✓ Верно'; }
  else if (r.hit > 0) { cls = 'part'; mark = '✓ Отчасти правильно'; }
  else                { cls = 'no';   mark = '✕ Не верно'; }

  document.getElementById('task-area').innerHTML = `
    <div class="task-q">${trEsc(it.q)}</div>
    <div class="tr-verdict">Ваш ответ: <b>${userAns ? trEsc(userAns) : '—'}</b>
      <span class="tr-st ${cls}">${mark}</span></div>
    <div class="tr-correct">Правильный ответ: <b>${trEsc(trKeyWords(it))}</b></div>
    <div class="task-vis tr-text">${trHighlight(it)}
      ${trSource(it)}</div>`;

  updScore();
  document.getElementById('fb').style.display = 'none';   // общая плашка не нужна
  document.getElementById('nxt-btn').style.display = 'block';   // «Далее»
}
